(2065705, 282380, 18799, '<td valign="top">It''s an ok sign, but not very dynamic I''m afraid.  The yellow border competes for attention - something a border should not do.</td>', 'It''s an ok sign, but not very dynamic I''m afraid.  The yellow border competes for attention - something a border should not do.', '2006-01-20 20:57:45.000000', NULL, 1),
(2065712, 282121, 18799, '<td valign="top">Well done.  I love the composition and the way you''ve captured both the great action as well as the sign.  a ten from me.</td>', 'Well done.  I love the composition and the way you''ve captured both the great action as well as the sign.  a ten from me.', '2006-01-20 20:59:31.000000', NULL, 1),
(2065713, 282051, 18799, '<td valign="top">That''s very funny, I love it.  9</td>', 'That''s very funny, I love it.  9', '2006-01-20 21:00:20.000000', NULL, 1),
(2065720, 282466, 18799, '<td valign="top">Great capture.  It took me a second to see the reflection.  8</td>', 'Great capture.  It took me a second to see the reflection.  8', '2006-01-20 21:02:35.000000', NULL, 1),
(2065726, 280861, 18799, '<td valign="top">interesting sky. Good choice with the color too.  8</td>', 'interesting sky. Good choice with the color too.  8', '2006-01-20 21:04:18.000000', NULL, 1),
