INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2065775, 282998, 18799, '<td valign="top">I don''t know what the title means, but I like the daring composition of this image.  The mirrored letters in the strong vertical postion coupled with the extreme negative space makes this image very compelling.  My only 10 so far.</td>', 'I don''t know what the title means, but I like the daring composition of this image.  The mirrored letters in the strong vertical postion coupled with the extreme negative space makes this image very compelling.  My only 10 so far.', '2006-01-20 21:14:32.000000', NULL, 1),
(2065777, 282858, 18799, '<td valign="top">LOL, great sense of humor.   8</td>', 'LOL, great sense of humor.   8', '2006-01-20 21:15:22.000000', NULL, 1),
(2065781, 282499, 18799, '<td valign="top">interesting compostion.  I like it.</td>', 'interesting compostion.  I like it.', '2006-01-20 21:16:19.000000', NULL, 1),
(2065799, 282363, 18799, '<td valign="top">Great hand - terrific texture and color treatment.  If I had a criticism, it would be that the rope isn''t as grizzled looking as the hand.  That would have pushed this to 10.  8</td>', 'Great hand - terrific texture and color treatment.  If I had a criticism, it would be that the rope isn''t as grizzled looking as the hand.  That would have pushed this to 10.  8', '2006-01-20 21:20:27.000000', NULL, 1),
(2065805, 282308, 18799, '<td valign="top">LOL   6</td>', 'LOL   6', '2006-01-20 21:21:51.000000', NULL, 1),
(2065810, 282709, 18799, '<td valign="top">It is evident that not much thought went into this image.</td>', 'It is evident that not much thought went into this image.', '2006-01-20 21:23:12.000000', NULL, 1),
(2065819, 282977, 39850, '<td valign="top">4 - Mostly for the potential - Good idea.  I think many will ''miss'' your ''effect'' here, I nearly did.  Criticism; mainly the composition and the reflections.  If the ''ghostly figure'' was either further into the frame, or else the frame cropped, a little more of the car perhaps, and the sign especially (as that is what the Challenge is about) ''placed'' better within the overall framing/composition (in this case likely ''left''), the reflections on the sign diminished (difficult, both for ''basic editing'' and the actual shooting/location) and cropping out/eliminating the upper left ''green sign'' - all have made this much better in my opinion.  Also, given the ''vertical nature'' of the two main subjects, perhaps a vertical framing may have worked better, but I realize you''ve tried to incorporate the ''crosswalk''.</td>', '4 - Mostly for the potential - Good idea.  I think many will ''miss'' your ''effect'' here, I nearly did.  Criticism; mainly the composition and the reflections.  If the ''ghostly figure'' was either further into the frame, or else the frame cropped, a little more of the car perhaps, and the sign especially (as that is what the Challenge is about) ''placed'' better within the overall framing/composition (in this case likely ''left''), the reflections on the sign diminished (difficult, both for ''basic editing'' and the actual shooting/location) and cropping out/eliminating the upper left ''green sign'' - all have made this much better in my opinion.  Also, given the ''vertical nature'' of the two main subjects, perhaps a vertical framing may have worked better, but I realize you''ve tried to incorporate the ''crosswalk''.', '2006-01-20 21:25:38.000000', NULL, 1),
(2065821, 282863, 18799, '<td valign="top">Really nice compostion of what would not otherwise be very interesting subjects.  I particularly like the attention to detail with the direction of the arrows.  The border works well with this image too.  9</td>', 'Really nice compostion of what would not otherwise be very interesting subjects.  I particularly like the attention to detail with the direction of the arrows.  The border works well with this image too.  9', '2006-01-20 21:26:07.000000', NULL, 1),
(2065827, 281239, 18799, '<td valign="top">I like the high key exposure that you''ve chosen.  8</td>', 'I like the high key exposure that you''ve chosen.  8', '2006-01-20 21:27:34.000000', NULL, 1),
(2065829, 282531, 18799, '<td valign="top">Good catch</td>', 'Good catch', '2006-01-20 21:28:36.000000', NULL, 1),
(2065835, 283011, 18799, '<td valign="top">The lighting is great and the shot is technically very well composed.  Not to nitpick, but the cut is the wrong direction and she wouldn''t be holding the blade like that. 6</td>', 'The lighting is great and the shot is technically very well composed.  Not to nitpick, but the cut is the wrong direction and she wouldn''t be holding the blade like that. 6', '2006-01-20 21:31:33.000000', NULL, 1),
(2065862, 282471, 18799, '<td valign="top">While I''m not one of Woodie''s biggest fans, this is well thought out and technically very well done.  I will break with tradition and give this a 9.  I have to say that I find the though of Woody being torn to splinters by an ancient raptor very agreeable.</td>', 'While I''m not one of Woodie''s biggest fans, this is well thought out and technically very well done.  I will break with tradition and give this a 9.  I have to say that I find the though of Woody being torn to splinters by an ancient raptor very agreeable.', '2006-01-20 21:39:56.000000', NULL, 1),
(2065871, 281906, 18799, '<td valign="top">Very busy, no focal point.</td>', 'Very busy, no focal point.', '2006-01-20 21:46:35.000000', NULL, 1),
(2065878, 279770, 4380, '<td valign="top">nice image, i like it</td>', 'nice image, i like it', '2006-01-20 21:48:46.000000', NULL, 1),
(2065882, 282939, 4380, '<td valign="top">perfectly composed, great image and i love the title... its a 10</td>', 'perfectly composed, great image and i love the title... its a 10', '2006-01-20 21:51:15.000000', NULL, 1),
(2065884, 282858, 4380, '<td valign="top">nicely presented, ilove the sepia tone</td>', 'nicely presented, ilove the sepia tone', '2006-01-20 21:52:11.000000', NULL, 1),
