(2069577, 281490, 42638, '<td valign="top">Beautiful, love the color against the white background.</td>', 'Beautiful, love the color against the white background.', '2006-01-21 23:59:01.000000', NULL, 1),
(2069579, 280908, 42638, '<td valign="top">Wonderful interpretation and good detail.</td>', 'Wonderful interpretation and good detail.', '2006-01-21 23:59:37.000000', NULL, 1),
(2069581, 282584, 42638, '<td valign="top">Wow, Fantastic picture. Love the colors and the cross is very powerful with that background. Nicely done!</td>', 'Wow, Fantastic picture. Love the colors and the cross is very powerful with that background. Nicely done!', '2006-01-22 00:00:46.000000', NULL, 1),
(2069584, 283010, 42638, '<td valign="top">Beautiful and crisp color here.</td>', 'Beautiful and crisp color here.', '2006-01-22 00:01:17.000000', NULL, 1),
(2069587, 282874, 42638, '<td valign="top">Nice and crisp focus. The washed out sky actually works with this one, well done.</td>', 'Nice and crisp focus. The washed out sky actually works with this one, well done.', '2006-01-22 00:02:35.000000', NULL, 1),
(2069589, 282688, 42638, '<td valign="top">Wow, nice picture of the destruction. Love the sky, so calm and beautiful behind such empty shells.</td>', 'Wow, nice picture of the destruction. Love the sky, so calm and beautiful behind such empty shells.', '2006-01-22 00:03:40.000000', NULL, 1),
(2069597, 282757, 42638, '<td valign="top">Very funny!! Good focus.</td>', 'Very funny!! Good focus.', '2006-01-22 00:07:06.000000', NULL, 1),
